       for name := range totals {
           productNames = append(productNames, name)
       }
       // Sort the product names alphabetically to ensure deterministic order
       sort.Strings(productNames)

       var parts []string
       // Iterate over the sorted product names
       for _, name := range productNames {
           total := totals[name] // Get the total for the current product name
           parts = append(parts, fmt.Sprintf("%s:%.2f", name, total))
       }
       report := strings.Join(parts, "|")

