    // type AuctionContract struct {
    // 	contractapi.Contract
    // }

    // PlaceBid function (modified to check auction status if needed)
    // ...

    // CloseAuction function (modified)
    func (a *AuctionContract) CloseAuction(ctx contractapi.TransactionContextInterface, auctionID string) error {
        // 1. Acquire a lock or set a "closing" status for the auction
        auctionStatusKey := "AUCTION_STATUS_" + auctionID
        statusBytes, err := ctx.GetStub().GetState(auctionStatusKey)
        if err != nil {
            return fmt.Errorf("failed to get auction status: %v", err)
        }
        if statusBytes != nil && string(statusBytes) == "CLOSING" {
            return fmt.Errorf("auction %s is already being closed", auctionID)
        }
        // Set status to CLOSING to prevent concurrent modifications
        err = ctx.GetStub().PutState(auctionStatusKey, []byte("CLOSING"))
        if err != nil {
            return fmt.Errorf("failed to set auction status to CLOSING: %v", err)
        }
        // Ensure status is reset/removed on commit or abort
        // This requires using transaction callbacks or careful error handling.
        // For simplicity, we'll assume successful commit removes the need for explicit rollback here.

        // 2. Proceed with reading bids (now safer due to the lock)
        resultsIterator, err := ctx.GetStub().GetStateByPartialCompositeKey("Bid", []string{auctionID})
        if err != nil {
            // Consider releasing lock here if error occurs before commit
            return fmt.Errorf("failed to query bids: %v", err)
        }
        defer resultsIterator.Close()

        var highestBid float64
        var highestBidder string
        totalBids := 0
        totalValue := 0.0

        for resultsIterator.HasNext() {
            queryResult, err := resultsIterator.Next()
            if err != nil {
                // Consider releasing lock here
                return err
            }

            var bid Bid
            err = json.Unmarshal(queryResult.Value, &bid)
            if err != nil {
                // Consider releasing lock here
                return fmt.Errorf("failed to unmarshal bid: %v", err)
            }

            totalBids++
            totalValue += bid.Amount

            if bid.Amount > highestBid {
                highestBid = bid.Amount
                highestBidder = bid.Bidder
            }
        }

        // 3. Write the summary
        summary := AuctionSummary{
            AuctionID:     auctionID,
            TotalBids:     totalBids,
            HighestBid:    highestBid,
            HighestBidder: highestBidder,
            TotalValue:    totalValue,
        }

        summaryJSON, err := json.Marshal(summary)
        if err != nil {
            // Consider releasing lock here
            return fmt.Errorf("failed to marshal summary: %v", err)
        }
        err = ctx.GetStub().PutState("AUCTION_RESULT_"+auctionID, summaryJSON)
        if err != nil {
            // Consider releasing lock here
            return fmt.Errorf("failed to put auction result: %v", err)
        }

        // 4. Optionally, remove the CLOSING status or set to CLOSED
        // If the transaction commits successfully, the state changes are committed.
        // If it aborts, the state changes are discarded.
        // The "CLOSING" status acts as a temporary lock.
        // A more robust solution might involve a persistent status field in an Auction object.

        return nil
    }
