        addPoints, err := strconv.Atoi(pointsStr)
        if err != nil {
            return fmt.Errorf("invalid points value: %v", err)
        }

        // Add checks for valid range and potential overflow
        const maxPoints = 2147483647 // Example: Max value for a 32-bit signed int
        const minPoints = 0        // Assuming points cannot be negative

        if addPoints < 0 {
            return fmt.Errorf("cannot add negative points: %d", addPoints)
        }
        if account.Points > maxPoints - addPoints {
            return fmt.Errorf("adding points would cause overflow: current %d, adding %d", account.Points, addPoints)
        }

        account.Points += addPoints
        // ... rest of the function ...
        ```

        **Example Fix for `RedeemPoints`**:

        ```go
        // ... inside RedeemPoints function ...

        if redeemAmount < 0 {
            return fmt.Errorf("cannot redeem negative points: %d", redeemAmount)
        }
        if account.Points < redeemAmount {
            return fmt.Errorf("insufficient points: have %d, need %d", account.Points, redeemAmount)
        }

        account.Points -= redeemAmount
        // ... rest of the function ...
        ```
        *Note: The exact `maxPoints` and `minPoints` should be chosen based on the expected range of loyalty points and the architecture's `int` size.*

