   txTimestamp, err := ctx.GetStub().GetTxTimestamp()
   if err != nil {
       return fmt.Errorf("failed to get transaction timestamp: %v", err)
   }
   // Convert google.protobuf.Timestamp to time.Time for formatting
   createdAtTime := time.Unix(txTimestamp.Seconds, int64(txTimestamp.Nanos))
   shipment.CreatedAt = createdAtTime.Format(time.RFC3339)
   shipment.UpdatedAt = createdAtTime.Format(time.RFC3339Nano) // Or RFC3339 if nanosecond precision is not strictly needed

   // In UpdateShipmentStatus:
