   if err != nil {
       return fmt.Errorf("failed to get transaction timestamp: %v", err)
   }
   updatedAtTime := time.Unix(txTimestamp.Seconds, int64(txTimestamp.Nanos))
   shipment.UpdatedAt = updatedAtTime.Format(time.RFC3339)

   // In RecordTemperature:
   txTimestamp, err := ctx.GetStub().GetTxTimestamp()
   if err != nil {
       return fmt.Errorf("failed to get transaction timestamp: %v", err)
   }
   recordedAtTime := time.Unix(txTimestamp.Seconds, int64(txTimestamp.Nanos))
   shipment.Temperature = fmt.Sprintf("%s°C at %s", tempCelsius, recordedAtTime.Format("15:04:05.000"))
   shipment.UpdatedAt = recordedAtTime.Format(time.RFC3339)
