       }
       sort.Strings(productNames) // Sort product names alphabetically

       var parts []string
       for _, name := range productNames {
           total := totals[name] // Access total using the sorted name
           parts = append(parts, fmt.Sprintf("%s:%.2f", name, total))
       }
       report := strings.Join(parts, "|")

